import AppKit

/// 轮询系统剪贴板，有变化就存一条记录。
final class ClipboardMonitor {
    /// 密码管理器等工具用来标记"不要记录"的类型（nspasteboard.org 约定）。
    static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
    ]

    /// 单条记录最多保存的原始数据量，超出的格式直接丢弃。
    static let maxBytes = 30 * 1024 * 1024

    var onNewClip: (() -> Void)?

    private let store: ClipStore
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    init(store: ClipStore) { self.store = store }

    func start() {
        let timer = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// 我们自己写入剪贴板（粘贴历史记录）时调用，避免把它当成新复制。
    func skipCurrent() { lastChange = NSPasteboard.general.changeCount }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount

        let settings = Settings.shared
        if settings.paused { return }

        let types = Set((pb.types ?? []).map(\.rawValue))
        if !types.isDisjoint(with: Self.sensitiveTypes) { return }

        let front = NSWorkspace.shared.frontmostApplication
        if settings.isExcluded(front?.bundleIdentifier) { return }

        guard let capture = Self.capture(pb) else { return }
        store.upsert(payload: capture.payload, identity: capture.identity, kind: capture.kind,
                     text: capture.text, thumb: capture.thumb,
                     sourceBundle: front?.bundleIdentifier, sourceName: front?.localizedName)
        onNewClip?()
    }

    private struct Capture {
        let payload: ClipPayload
        let identity: Data
        let kind: ClipKind
        let text: String
        let thumb: Data?
    }

    private static func capture(_ pb: NSPasteboard) -> Capture? {
        guard let items = pb.pasteboardItems, !items.isEmpty else { return nil }

        var payload: ClipPayload = []
        var total = 0
        for item in items {
            var dict: [String: Data] = [:]
            for type in item.types where keep(type.rawValue) {
                guard let data = item.data(forType: type), total + data.count <= maxBytes else { continue }
                dict[type.rawValue] = data
                total += data.count
            }
            if !dict.isEmpty { payload.append(dict) }
        }
        guard !payload.isEmpty else { return nil }

        let typeNames = Set(payload.flatMap(\.keys))
        let fileURLs = (pb.readObjects(forClasses: [NSURL.self],
                                       options: [.urlReadingFileURLsOnly: true]) as? [URL]) ?? []

        if !fileURLs.isEmpty {
            let text = fileURLs.map(\.path).joined(separator: "\n")
            return Capture(payload: payload, identity: Data(text.utf8), kind: .file, text: text, thumb: nil)
        }

        if let string = pb.string(forType: .string),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            let rich = typeNames.contains(NSPasteboard.PasteboardType.rtf.rawValue)
                || typeNames.contains(NSPasteboard.PasteboardType.html.rawValue)
            return Capture(payload: payload, identity: Data(string.utf8), kind: rich ? .rich : .text,
                           text: String(string.prefix(20_000)), thumb: nil)
        }

        if let image = NSImage(pasteboard: pb),
           let cg = image.cgImage(forProposedRect: nil, context: nil, hints: nil) {
            let raw = payload.first?[NSPasteboard.PasteboardType.png.rawValue]
                ?? payload.first?[NSPasteboard.PasteboardType.tiff.rawValue]
                ?? Data("\(cg.width)x\(cg.height)-\(total)".utf8)
            return Capture(payload: payload, identity: raw, kind: .image,
                           text: "图片 \(cg.width)×\(cg.height)", thumb: thumbnail(cg))
        }
        return nil
    }

    /// 过滤掉旧式、重复的剪贴板类型，只留现代 UTI。
    private static func keep(_ type: String) -> Bool {
        if type.hasPrefix("dyn.") || type.hasPrefix("NeXT") || type.hasPrefix("Apple ") { return false }
        if type.hasPrefix("NS") && type.hasSuffix("PboardType") { return false }
        if type == "CorePasteboardFlavorType" || type.hasPrefix("com.apple.pasteboard.promised") { return false }
        return true
    }

    private static func thumbnail(_ cg: CGImage, maxSide: CGFloat = 320) -> Data? {
        let scale = min(1, maxSide / CGFloat(max(cg.width, cg.height)))
        let w = max(1, Int(CGFloat(cg.width) * scale)), h = max(1, Int(CGFloat(cg.height) * scale))
        guard let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0,
                                  space: CGColorSpaceCreateDeviceRGB(),
                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        ctx.interpolationQuality = .high
        ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))
        guard let out = ctx.makeImage() else { return nil }
        return NSBitmapImageRep(cgImage: out).representation(using: .png, properties: [:])
    }
}
